<div class="sl-head"><div><h1 class="sl-title row g8" style="font-size:20px">Live API traffic <span class="sl-badge row g6"><span class="at-dot live" id="at-dot"></span><span id="at-live">Live · refreshes every 15 s</span></span></h1><p class="sl-lede">Every call Swift Lane makes (pull) and every call its API receives (push). Click a line to see the details.</p></div><div class="row g8 wrap"><div class="sl-seg boxed"><?php foreach ($d['dirs'] as $x): ?><a class="<?= $x['k'] === $d['dir'] ? 'on' : '' ?>" href="<?= h(sl_url(['dir' => $x['k']])) ?>"><?= h($x['label']) ?></a><?php endforeach; ?></div><button class="sl-btn ghost" type="button" id="at-pause"><i class="ic ic-sm i-pause" aria-hidden="true"></i><span>Pause</span></button><a class="sl-btn ghost" href="<?= sl_route('ApiMonitor') ?>"><i class="ic ic-sm i-chart" aria-hidden="true"></i>Monitoring</a></div></div>
<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(min(170px,100%),1fr));gap:12px"><?php foreach ($d['kpis'] as $k): ?><div class="at-k"><small><?= h($k['l']) ?></small><b><?= h($k['v']) ?></b><small><?= h($k['s']) ?></small></div><?php endforeach; ?></div>
<div class="at-pv"><?php foreach ($d['provs'] as $p): ?><div class="at-p"><span class="row g8"><span class="at-dot <?= h($p['dot']) ?>"></span><b class="fw5 sm grow"><?= h($p['n']) ?></b><span class="mono mut" style="font-size:13.5px"><?= h($p['ms']) ?></span></span><span class="mut" style="font-size:14px"><?= h($p['kind']) ?> · <?= h($p['rate']) ?></span><div class="at-sp" aria-hidden="true"><?php foreach ($p['sp'] as $hh): ?><i title="<?= h($hh['t']) ?>" class="<?= h($hh['c']) ?>" style="<?= h($hh['s']) ?>"></i><?php endforeach; ?></div></div><?php endforeach; ?></div>
<div class="at-two">
<?php foreach (['pull' => ['Pull · calls we make', 'Messages to SMS, WhatsApp and e-mail providers', 'i-upload', 'pullN'], 'push' => ['Push · calls we receive', 'Requests to the Swift Lane REST API', 'i-download', 'pushN']] as $k => $m): if (!$d['show' . ucfirst($k)]) continue; ?>
<section class="at-s"><div class="at-sh"><span class="at-dir"><i class="ic ic-sm <?= $m[2] ?>" aria-hidden="true"></i></span><div class="col grow"><b class="fw5"><?= h($m[0]) ?></b><span class="mut sm"><?= h($m[1]) ?></span></div><span class="mono sm"><?= (int) $d[$m[3]] ?>/min</span></div><div class="at-list" role="log"><?php foreach ($d[$k] as $l): ?><button type="button" class="at-l <?= $sel && $sel['id'] === $l['id'] ? 'on' : '' ?>" data-at-json="<?= h($l['json']) ?>" data-at-title="<?= h($l['p'] . ' · ' . $l['e']) ?>" data-at-code="<?= (int) $l['code'] ?>"><span class="t"><?= h($l['t']) ?></span><span class="p"><?= h($l['p']) ?></span><span class="e"><?= h($l['e']) ?></span><span class="at-c <?= h($l['cc']) ?>"><?= (int) $l['code'] ?></span><span class="ms"><?= h($l['ms']) ?></span></button><?php endforeach; ?><?php if (!$d[$k]): ?><div class="mut sm" style="padding:14px">Nothing recorded yet.</div><?php endif; ?></div></section>
<?php endforeach; ?>
</div>
<div class="split"><section class="a sl-card col g12"><div class="sl-ch" style="margin:0"><div><h2 class="sl-ct" id="at-title"><?= h($sel ? $sel['p'] . ' · ' . $sel['e'] : 'Pick a line') ?></h2></div><span class="at-c <?= h($sel['cc'] ?? '') ?>" style="padding:0 8px" id="at-code"><?= (int) ($sel['code'] ?? 0) ?></span></div>
