<script>
(function(){
  var paused = false, t = setInterval(function(){ if (!paused) location.reload(); }, 15000);
  document.getElementById('at-pause').addEventListener('click', function(){ paused = !paused; this.querySelector('span').textContent = paused ? 'Resume' : 'Pause'; document.getElementById('at-live').textContent = paused ? 'Paused' : 'Live · refreshes every 15 s'; document.getElementById('at-dot').className = 'at-dot ' + (paused ? 'off' : 'live'); });
  document.addEventListener('click', function(e){ var b = e.target.closest('[data-at-json]'); if (!b) return; document.querySelectorAll('.at-l.on').forEach(function(x){ x.classList.remove('on'); }); b.classList.add('on'); document.getElementById('at-json').textContent = b.getAttribute('data-at-json'); document.getElementById('at-title').textContent = b.getAttribute('data-at-title'); document.getElementById('at-code').textContent = b.getAttribute('data-at-code'); paused = true; document.getElementById('at-pause').querySelector('span').textContent = 'Resume'; });
})();
</script>
